<script setup>
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import AppShell from '@/components/shell/AppShell.vue'
import ExerciseShell from '@/components/exercise/ExerciseShell.vue'
import QuestionAnswer from '@/components/exercise/QuestionAnswer.vue'
import QuestionNavigator from '@/components/exercise/QuestionNavigator.vue'
import SubmitOverview from '@/components/common/SubmitOverview.vue'
import { renderMarkdown } from '@/utils/markdown'
import { usePracticeStore } from '@/stores/practiceStore'
const route=useRoute(),router=useRouter(),store=usePracticeStore(),overviewOpen=ref(false),diagnosticChoice=ref('')
const q=computed(()=>store.currentQuestion),feedback=computed(()=>q.value&&store.feedback[q.value.question_id]),diagnostic=computed(()=>q.value&&store.diagnostics[q.value.question_id])
const hintVisible=computed(()=>q.value&&store.showHint[q.value.question_id]),hintText=computed(()=>Array.isArray(q.value?.common_mistakes)?q.value.common_mistakes.filter(Boolean).join('；'):q.value?.common_mistakes)
const answeredCount=computed(()=>Object.keys(store.feedback).length),pendingCount=computed(()=>(store.session?.questions?.length||0)-answeredCount.value),canRetry=computed(()=>q.value?store.canRetry(q.value.question_id):false)
const behaviorLabel=computed(()=>({immediate:'即时反馈',adaptive:'自适应练习',deferred:'统一反馈'}[store.behavior]||'自适应练习'))
const states=computed(()=>Object.fromEntries(Object.entries(store.feedback).map(([id,fb])=>[id,fb.feedback_deferred?'submitted':fb.correct?'correct':'wrong'])))
let snapshotTimer
onMounted(async()=>{await store.loadSession(route.params.sessionId);if(store.session.status==='completed'){router.replace(`/apply/practice/sessions/${route.params.sessionId}/result`);return}if(store.session.status==='created')await store.start();snapshotTimer=setInterval(()=>store.saveSnapshot(),30000);globalThis.addEventListener?.('pagehide',store.saveSnapshot)})
onUnmounted(()=>{clearInterval(snapshotTimer);globalThis.removeEventListener?.('pagehide',store.saveSnapshot)})
async function finish(){if(pendingCount.value&&!overviewOpen.value){overviewOpen.value=true;return}overviewOpen.value=false;await store.complete();router.push({path:`/apply/practice/sessions/${route.params.sessionId}/result`,query:route.query.return_to?{return_to:route.query.return_to}:{}})}
async function beginDiagnostic(){diagnosticChoice.value='';await store.startDiagnostic(q.value.question_id)}
async function answerDiagnostic(){if(!diagnosticChoice.value)return;await store.answerDiagnostic(q.value.question_id,diagnosticChoice.value)}
function retry(){diagnosticChoice.value='';store.beginRetry(q.value.question_id)}
function jump(index){overviewOpen.value=false;store.currentIndex=index}
</script>
<template><AppShell><template #topbar-title>练习</template><ExerciseShell v-if="q" :question="q" :total="store.session.questions.length" :status-text="`${behaviorLabel} · 已提交 ${answeredCount} 题`"><template #alert><p v-if="store.error" class="error" role="alert">{{store.error}}</p></template><QuestionAnswer v-model="store.answers[q.question_id]" :question="q" :disabled="!!feedback"/><div v-if="!feedback" class="learning-actions"><button v-if="hintText" @click="store.revealHint(q.question_id)">{{hintVisible?'收起提示':'查看方向提示'}}</button><button :class="{marked:store.uncertain[q.question_id]}" @click="store.markUncertain(q.question_id)">{{store.uncertain[q.question_id]?'已标记不确定':'我不确定'}}</button></div><p v-if="hintVisible&&!feedback" class="hint">{{hintText}}</p><template #feedback><section v-if="feedback" class="feedback" :class="feedback.feedback_deferred?'deferred':feedback.correct?'correct':'incorrect'"><template v-if="feedback.feedback_deferred"><strong>已保存本题答案</strong><p>完成练习后统一查看正误和解析。</p></template><template v-else-if="feedback.correct"><strong>回答正确</strong><div v-if="feedback.analysis" v-html="renderMarkdown(feedback.analysis)"/></template><template v-else><strong>这一步还不对，先找方向</strong><p v-if="canRetry">正确答案暂不展示。你可以重试，或用一道微问题定位卡点。</p><template v-if="diagnostic&&!diagnostic.completed"><div class="diagnostic"><p>{{diagnostic.prompt}}</p><label v-for="option in diagnostic.options" :key="option.id"><input v-model="diagnosticChoice" type="radio" :value="option.id">{{option.id}}. {{option.text}}</label><button :disabled="!diagnosticChoice" @click="answerDiagnostic">确认判断</button></div></template><div v-else-if="diagnostic?.completed" class="diagnostic-result"><strong>{{diagnostic.correct?'定位正确':'已记录这个卡点'}}</strong><p>{{diagnostic.follow_up}}</p></div><div v-if="canRetry" class="retry-row"><button @click="retry">再试一次</button><button v-if="!diagnostic" @click="beginDiagnostic">诊断一下</button></div><template v-else><p>正确答案：{{feedback.correct_answer}}</p><div v-if="feedback.analysis" v-html="renderMarkdown(feedback.analysis)"/></template></template></section></template><template #actions><nav><button :disabled="store.currentIndex===0" @click="store.currentIndex--">上一题</button><QuestionNavigator :questions="store.session.questions" :answers="store.answers" :current-index="store.currentIndex" :states="states" :uncertain="store.uncertain" @jump="jump"/><button v-if="store.currentIndex<store.session.questions.length-1" @click="store.currentIndex++">下一题</button><button v-else class="primary" @click="finish">完成练习</button></nav><div class="submit-row"><button v-if="!feedback" class="primary" :disabled="store.loading||store.answers[q.question_id]===undefined||store.answers[q.question_id]===''" @click="store.submitCurrent">提交本题</button></div></template></ExerciseShell><p v-else class="loading">正在恢复练习…</p><SubmitOverview :visible="overviewOpen" :questions="store.session?.questions||[]" :answers="store.answers" :current-index="store.currentIndex" :submitting="store.loading" title="完成前总览 · 练习" @confirm="finish" @cancel="overviewOpen=false" @jump="jump"/></AppShell></template>
<style scoped>.learning-actions,.retry-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.learning-actions button,.retry-row button,.diagnostic button,nav button,.submit-row button{min-height:42px;padding:0 15px;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface);color:var(--text-primary);cursor:pointer}.learning-actions .marked{border-color:#d89000;color:#9a6200;background:#fff7dc}.hint,.diagnostic-result{padding:12px 14px;border-radius:var(--radius-sm);background:var(--accent-soft)}.feedback{margin-top:18px;padding:22px;border:1px solid var(--border-subtle);border-left:4px solid var(--danger);border-radius:var(--radius-lg);background:var(--surface)}.feedback.correct{border-left-color:var(--success)}.feedback.deferred{border-left-color:var(--accent)}.diagnostic{display:grid;gap:10px;margin-top:14px;padding:16px;background:var(--surface-muted);border-radius:var(--radius-sm)}.diagnostic label{display:flex;gap:8px}.error{color:var(--danger)}nav{display:flex;align-items:center;gap:12px;margin-top:22px}.primary{background:var(--accent)!important;color:#fff!important;border-color:var(--accent)!important}.submit-row{display:flex;justify-content:flex-end;margin-top:14px}.loading{padding:32px}@media(max-width:600px){nav{flex-wrap:wrap}nav :deep(.navigator){order:3;flex-basis:100%}}</style>
